@implementation INSpeakableStringResolutionResult

+ (instancetype)successWithResolvedString:(INSpeakableString *)resolvedString
{
    // The host re-forms a success carrying the zero case of its type as a
    // notRequired - a success with nothing to say - and leaves any other value a
    // success (measured on the host's own Intents, 17 enumerations).
    return [self charon_resolutionWithStatus:resolvedString == 0 ? CharonIntentsResolutionNotRequired
                                                : CharonIntentsResolutionSuccess
 resolvedValue:[resolvedString copy] valuesToDisambiguate:nil valueToConfirm:nil];
}

+ (instancetype)disambiguationWithStringsToDisambiguate:(NSArray<INSpeakableString *> *)stringsToDisambiguate
{
    return [self charon_resolutionWithStatus:CharonIntentsResolutionDisambiguation resolvedValue:nil valuesToDisambiguate:[stringsToDisambiguate copy] valueToConfirm:nil];
}

+ (instancetype)confirmationRequiredWithStringToConfirm:(INSpeakableString *)stringToConfirm
{
    return [self charon_resolutionWithStatus:CharonIntentsResolutionConfirmationRequired resolvedValue:nil valuesToDisambiguate:nil valueToConfirm:[stringToConfirm copy]];
}

@end

